}

{
  "query": "mutation Registrar($input: RegistrarUsuarioInput!) { registrarme(input: $input) { id nombre email rol } }",
  "variables": {
    "input": {
      "nombre": "Carlos Trainer",
      "email": "carlos@cuspian.com",
