}

{
  "query": "mutation CrearEntrenador($input: EntrenadorInput!) { crearEntrenador(input: $input) { id usuario_id especialidades biografia certificaciones } }",
  "variables": {
    "input": {
      "usuario_id": 2,
      "especialidades": "Yoga, Pilates",
      "biografia": "10 años de experiencia en yoga y pilates",
      "certificaciones": "RYT-500, STOTT Pilates"
    }
  }
}

{
  "query": "mutation ActualizarEntrenador($id: ID!, $input: ActualizarEntrenadorInput!) { actualizarEntrenador(id: $id, input: $input) { id especialidades } }",
  "variables": {
    "id": "1",
    "input": { "especialidades": "Yoga, Pilates, TRX" }
  }
}

{
  "query": "mutation CrearSala($input: SalaInput!) { crearSala(input: $input) { id nombre capacidad_maxima descripcion estado } }",
  "variables": {
    "input": {
      "nombre": "Sala Principal",
      "capacidad_maxima": 20,
      "descripcion": "Sala equipada para clases grupales",
      "estado": "activa"
    }
  }
}

{
  "query": "mutation ActualizarSala($id: ID!, $input: ActualizarSalaInput!) { actualizarSala(id: $id, input: $input) { id nombre capacidad_maxima estado } }",
  "variables": {
    "id": "1",
    "input": { "capacidad_maxima": 25 }
  }
}

{
  "query": "mutation CrearServicio($input: ServicioInput!) { crearServicio(input: $input) { id nombre descripcion duracion_minutos estado } }",
  "variables": {
    "input": {
      "nombre": "Yoga Matutino",
      "descripcion": "Clase de yoga para principiantes",
      "duracion_minutos": 60,
      "estado": "activo"
    }
  }
}

{
  "query": "mutation ActualizarServicio($id: ID!, $input: ActualizarServicioInput!) { actualizarServicio(id: $id, input: $input) { id nombre duracion_minutos } }",
  "variables": {
    "id": "1",
    "input": { "duracion_minutos": 75 }
  }
}

{
  "query": "mutation CrearPlan($input: PlanInput!) { crearPlan(input: $input) { id nombre descripcion precio clases_por_mes invitados_por_mes activo } }",
  "variables": {
    "input": {
      "nombre": "Plan Básico",
      "descripcion": "12 clases al mes con cualquier entrenador",
      "precio": 150000,
      "clases_por_mes": 12,
      "invitados_por_mes": 0,
      "activo": true
    }
  }
}

{
  "query": "mutation CrearPlan($input: PlanInput!) { crearPlan(input: $input) { id nombre precio clases_por_mes } }",
  "variables": {
    "input": {
      "nombre": "Plan Ilimitado",
      "descripcion": "Clases ilimitadas al mes — acceso a cualquier sala y servicio",
      "precio": 300000,
      "clases_por_mes": null,
      "invitados_por_mes": 2,
      "activo": true
    }
  }
}

{
  "query": "mutation ActualizarPlan($id: ID!, $input: ActualizarPlanInput!) { actualizarPlan(id: $id, input: $input) { id nombre precio activo } }",
  "variables": {
    "id": "1",
    "input": { "precio": 160000, "activo": true }
  }
}

{
  "query": "mutation CrearHorario($input: HorarioInput!) { crearHorario(input: $input) { id servicio_id sala_id entrenador_id dia_semana hora_inicio hora_fin cupo_maximo estado } }",
  "variables": {
    "input": {
      "servicio_id": 1,
      "sala_id": 1,
      "entrenador_id": 1,
      "dia_semana": 1,
      "hora_inicio": "07:00",
      "hora_fin": "08:00",
      "cupo_maximo": 15,
      "estado": "activo"
    }
  }
}

{
  "query": "query HorariosDisponibles($servicio_id: Int!) { horariosDisponibles(servicio_id: $servicio_id) { id dia_semana hora_inicio hora_fin cupo_maximo estado } }",
  "variables": { "servicio_id": 1 }
}

{
  "query": "mutation ActualizarHorario($id: ID!, $input: ActualizarHorarioInput!) { actualizarHorario(id: $id, input: $input) { id hora_inicio hora_fin cupo_maximo estado } }",
  "variables": {
    "id": "1",
    "input": { "cupo_maximo": 20 }
  }
}

{
  "query": "mutation EliminarHorario($id: ID!) { eliminarHorario(id: $id) { id } }",
  "variables": { "id": "1" }
}

{
  "query": "mutation RegistrarPago($input: PagoInput!) { registrarPago(input: $input) { id usuario_id suscripcion_id concepto monto metodo_pago estado fecha_pago } }",
  "variables": {
    "input": {
      "usuario_id": 1,
      "suscripcion_id": 1,
      "concepto": "Suscripción Plan Básico — Octubre 2026",
      "monto": 150000,
      "metodo_pago": "transferencia"
    }
  }
}

{
  "query": "mutation RegistrarPago($input: PagoInput!) { registrarPago(input: $input) { id concepto monto estado } }",
  "variables": {
    "input": {
      "usuario_id": 1,
      "concepto": "Clase individual Yoga Matutino — 2026-09-15",
      "monto": 35000,
      "metodo_pago": "efectivo"
    }
  }
}

{
  "query": "query ReporteVentas($fecha_inicio: String, $fecha_fin: String) { reporteVentas(fecha_inicio: $fecha_inicio, fecha_fin: $fecha_fin) { total_ingresos total_pagos detalles { id concepto monto fecha_pago } } }",
  "variables": {
    "fecha_inicio": "2026-09-01",
    "fecha_fin": "2026-09-30"
  }
}

{
  "query": "mutation RegistrarGasto($input: GastoEntrenadorInput!) { registrarGastoEntrenador(input: $input) { id entrenador_id concepto monto metodo_pago fecha_pago notas } }",
  "variables": {
    "input": {
      "entrenador_id": 1,
      "concepto": "Pago clases semana 37 — Septiembre 2026",
      "monto": 450000,
      "metodo_pago": "transferencia",
      "notas": "18 clases dictadas a $25.000 c/u"
    }
  }
}

{
  "query": "query GastosEntrenador($entrenador_id: Int!) { gastosEntrenador(entrenador_id: $entrenador_id) { id concepto monto fecha_pago notas } }",
  "variables": { "entrenador_id": 1 }
}

{
  "query": "query ReservasPorFecha($fecha: String!) { reservasPorFecha(fecha: $fecha) { id usuario_id horario_id estado } }",
  "variables": { "fecha": "2026-09-15" }
}

{
  "query": "mutation ActivarSuscripcion($suscripcion_id: Int!) { activarSuscripcion(suscripcion_id: $suscripcion_id) { id estado pagado } }",
  "variables": { "suscripcion_id": 1 }
}

{
  "query": "query MisHorarios($entrenador_id: Int!) { misHorarios(entrenador_id: $entrenador_id) { id servicio_id sala_id dia_semana hora_inicio hora_fin cupo_maximo estado } }",
  "variables": { "entrenador_id": 1 }
}

{
  "query": "query ReservasPorHorario($horario_id: Int!) { reservasPorHorario(horario_id: $horario_id) { id usuario_id fecha estado } }",
