}

{
  "query": "query PagosPorEntrenador($entrenador_id: Int!) { pagosPorEntrenador(entrenador_id: $entrenador_id) { id concepto monto metodo_pago fecha_pago notas } }",
  "variables": { "entrenador_id": 1 }
}

{
  "query": "mutation Suscribirme($usuario_id: Int!, $plan_id: Int!) { suscribirme(usuario_id: $usuario_id, plan_id: $plan_id) { id usuario_id plan_id fecha_inicio fecha_fin estado clases_usadas_mes pagado } }",
  "variables": { "usuario_id": 1, "plan_id": 1 }
}

{
  "query": "query MiSuscripcion($usuario_id: Int!) { miSuscripcion(usuario_id: $usuario_id) { id plan_id fecha_inicio fecha_fin estado clases_usadas_mes pagado } }",
