  "variables": {
    "usuario_id": 1,
    "horario_id": 1,
    "fecha": "2026-09-15"
  }
}

{
  "query": "mutation ReservarPuntual($usuario_id: Int!, $horario_id: Int!, $fecha: String!) { reservarServicioPuntual(usuario_id: $usuario_id, horario_id: $horario_id, fecha: $fecha) { id usuario_id horario_id fecha estado } }",
  "variables": {
    "usuario_id": 1,
    "horario_id": 1,
    "fecha": "2026-09-20"
  }
}

{
